import "server-only";

import type { SubscriptionStatus } from "@/generated/prisma/client";
import { db } from "@/lib/db";
import { BillingError, billingConfig } from "@/lib/billing/config";
import { dodoClient } from "@/lib/billing/dodo";
import {
  normalizedBillingSchema,
  normalizedPaymentSchema,
  normalizedSubscriptionSchema,
  providerSubscriptionSchema,
} from "@/lib/billing/events";
import { ensureBillingBinding } from "@/lib/billing/store";
import { recoverRetainedDeletion, runDeletionJob } from "@/lib/deletion-jobs";
import { withUsageTransaction } from "@/lib/usage-ledger";

// A provider active status is not settlement proof. Periods are selected only
// from verified payment.succeeded inbox rows for this customer/subscription.
// A localized payment can use a different currency from the subscription; its
// signed service_periods establish coverage, not currency or amount conversion.
export async function reconcileBillingSubscription(
  userId: string,
  subscriptionId: string,
  eventId?: string,
) {
  let previousSnapshot: string | null = null;
  for (let retry = 0; retry < 3; retry++) {
    const before = await db.user.findUniqueOrThrow({
      where: { id: userId },
      select: { dodoCustomerId: true, billingStateVersion: true },
    });
    const fetchStarted = new Date();
    const provider = providerSubscriptionSchema.parse(
      await dodoClient().subscriptions.retrieve(subscriptionId),
    );
    const config = billingConfig();
    const snapshot = JSON.stringify([
      provider.status,
      provider.previous_billing_date,
      provider.next_billing_date,
      provider.cancel_at_next_billing_date,
    ]);
    const snapshotRepeated = previousSnapshot === snapshot;
    previousSnapshot = snapshot;
    if (
      provider.subscription_id !== subscriptionId ||
      provider.customer.customer_id !== before.dodoCustomerId ||
      (provider.metadata.mailloopUserId &&
        provider.metadata.mailloopUserId !== userId)
    )
      throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");

    const result = await withUsageTransaction(db, userId, async ({ tx }) => {
      await ensureBillingBinding(tx);
      const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
      if (
        eventId &&
        (
          await tx.billingWebhookEvent.findUniqueOrThrow({
            where: { id: eventId },
            select: { processedAt: true },
          })
        ).processedAt
      )
        return true;
      if (user.billingStateVersion !== before.billingStateVersion) return false;
      if (user.deletionRequestedAt)
        throw new BillingError("ACCOUNT_UNAVAILABLE");
      const finishEvent = async () => {
        if (eventId)
          await tx.billingWebhookEvent.updateMany({
            where: { id: eventId, processedAt: null },
            data: {
              state: "PROCESSED",
              processedAt: new Date(),
              nextAttemptAt: null,
              failureCode: null,
              attempts: { increment: 1 },
            },
          });
      };
      const existing = await tx.billingSubscription.findFirst({
        where: { userId, dodoSubscriptionId: subscriptionId },
      });
      const otherOwner = await tx.billingSubscription.findUnique({
        where: { dodoSubscriptionId: subscriptionId },
        select: { userId: true },
      });
      if (otherOwner && otherOwner.userId !== userId)
        throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
      // This release sells one fixed product. A portal/dashboard plan change
      // cannot reuse an older product's payment as proof for the allowed plan.
      // Keep the drifted product as a review marker, including if it changes
      // back. Cancellation followed by a new checkout establishes fresh proof.
      if (
        provider.product_id !== config.productId ||
        (existing && existing.productId !== config.productId)
      ) {
        if (!existing)
          throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
        await tx.billingSubscription.updateMany({
          where: { userId, dodoSubscriptionId: subscriptionId },
          data: {
            productId:
              provider.product_id !== config.productId
                ? provider.product_id
                : existing.productId,
            status: provider.status.toUpperCase() as SubscriptionStatus,
            cancelAtPeriodEnd: provider.cancel_at_next_billing_date,
            cancelRequestedAt:
              provider.cancel_at_next_billing_date ||
              ["cancelled", "expired", "failed"].includes(provider.status)
                ? null
                : existing.cancelRequestedAt,
          },
        });
        await tx.user.updateMany({
          where: { id: userId, dodoSubscriptionId: subscriptionId },
          data: {
            plan: "FREE",
            cancelAtPeriodEnd: provider.cancel_at_next_billing_date,
            subscriptionStatus:
              provider.status.toUpperCase() as SubscriptionStatus,
            gracePeriodEnd: null,
            billingStateVersion: { increment: 1 },
          },
        });
        return "unsupported" as const;
      }
      if (
        provider.metadata.checkoutAttemptId &&
        !(await tx.checkoutAttempt.findFirst({
          where: { id: provider.metadata.checkoutAttemptId, userId },
          select: { id: true },
        }))
      )
        throw new BillingError("CHECKOUT_OWNERSHIP_MISMATCH");
      const events = await tx.billingWebhookEvent.findMany({
        where: {
          businessId: config.businessId,
          customerId: user.dodoCustomerId!,
          subscriptionId,
          state: { notIn: ["QUARANTINED", "IGNORED"] },
        },
        orderBy: [{ occurredAt: "desc" }, { id: "desc" }],
      });
      const arrivedDuringFetch = events
        .filter((e) => e.receivedAt >= fetchStarted)
        .map((e) => normalizedSubscriptionSchema.safeParse(e.normalizedData))
        .find((e) => e.success);
      if (
        arrivedDuringFetch?.success &&
        (arrivedDuringFetch.data.subscription.status !== provider.status ||
          new Date(
            arrivedDuringFetch.data.subscription.next_billing_date,
          ).getTime() !== new Date(provider.next_billing_date).getTime())
      )
        return false;
      const latestSignedSubscription = events
        .map((e) => normalizedSubscriptionSchema.safeParse(e.normalizedData))
        .find((e) => e.success);
      if (!snapshotRepeated && latestSignedSubscription?.success) {
        const signed = latestSignedSubscription.data.subscription;
        if (
          signed.status !== provider.status ||
          signed.previous_billing_date !== provider.previous_billing_date ||
          signed.next_billing_date !== provider.next_billing_date ||
          signed.cancel_at_next_billing_date !==
            provider.cancel_at_next_billing_date
        )
          return false; // Recheck a conflicting API snapshot before trusting it.
      }
      const paymentData = events
        .filter((e) => e.eventType === "payment.succeeded")
        .map((e) => normalizedPaymentSchema.safeParse(e.normalizedData))
        .filter((p) => p.success)
        .map((p) => p.data);
      const ownedAttempts = await tx.checkoutAttempt.findMany({
        where: {
          userId,
          id: {
            in: paymentData
              .map((p) => p.metadata.checkoutAttemptId)
              .filter((id): id is string => Boolean(id)),
          },
        },
        select: { id: true },
      });
      const ownedAttemptIds = new Set(ownedAttempts.map((a) => a.id));
      const settlements = events
        .filter((e) => e.eventType === "payment.succeeded")
        .map((e) => normalizedPaymentSchema.safeParse(e.normalizedData))
        .filter((p) => p.success)
        .map((p) => p.data)
        .filter(
          (p) =>
            p.succeeded &&
            p.amount > 0 &&
            p.startsAt &&
            p.endsAt &&
            new Date(p.startsAt) < new Date(p.endsAt) &&
            (!p.metadata.checkoutAttemptId ||
              ownedAttemptIds.has(p.metadata.checkoutAttemptId)) &&
            (!p.metadata.mailloopUserId ||
              p.metadata.mailloopUserId === userId) &&
            p.customerId === user.dodoCustomerId &&
            p.subscriptionId === subscriptionId,
        );
      const paidCandidate = settlements.sort(
        (a, b) => new Date(b.endsAt!).getTime() - new Date(a.endsAt!).getTime(),
      )[0];
      if (
        paidCandidate &&
        new Date(paidCandidate.endsAt!) >
          new Date(provider.next_billing_date) &&
        !["cancelled", "expired", "failed"].includes(provider.status)
      )
        return false;
      if (
        paidCandidate &&
        existing?.periodEnd &&
        new Date(paidCandidate.endsAt!).getTime() ===
          existing.periodEnd.getTime() &&
        existing.periodStart &&
        new Date(paidCandidate.startsAt!).getTime() !==
          existing.periodStart.getTime()
      )
        throw new BillingError("CONFLICTING_SETTLEMENT_PERIOD");
      const paid =
        paidCandidate &&
        (!existing?.periodEnd ||
          new Date(paidCandidate.endsAt!) >= existing.periodEnd)
          ? paidCandidate
          : undefined;
      // A regressed GET cannot overwrite newer settled history. Retry the read.
      if (
        existing?.periodEnd &&
        new Date(provider.next_billing_date) < existing.periodEnd &&
        !["cancelled", "expired", "failed"].includes(provider.status)
      )
        return false;
      const periodStart = paid
        ? new Date(paid.startsAt!)
        : (existing?.periodStart ?? null);
      const periodEnd = paid
        ? new Date(paid.endsAt!)
        : (existing?.periodEnd ?? null);
      const settledPaymentId =
        paid?.paymentId ?? existing?.settledPaymentId ?? null;
      const hasPayment = Boolean(settledPaymentId && periodStart && periodEnd);
      // Retrieval currently omits grace deadline. Only accept a signed snapshot
      // whose status and provider billing dates still match the retrieved state.
      const graceEvent = events
        .map((e) => normalizedSubscriptionSchema.safeParse(e.normalizedData))
        .filter((e) => e.success)
        .map((e) => e.data.subscription)
        .find(
          (s) =>
            s.status === "past_due" &&
            new Date(s.previous_billing_date).getTime() ===
              new Date(provider.previous_billing_date).getTime() &&
            new Date(s.next_billing_date).getTime() ===
              new Date(provider.next_billing_date).getTime() &&
            s.past_due_ends_at,
        );
      const grace =
        provider.status === "past_due"
          ? graceEvent?.past_due_ends_at
          : ["active", "on_hold", "paused"].includes(provider.status) &&
              existing?.gracePeriodEnd &&
              (!paid || new Date(paid.startsAt!) <= existing.periodStart!)
            ? existing.gracePeriodEnd.toISOString()
            : null;
      const gracePeriodEnd =
        hasPayment && grace && new Date(grace) >= periodEnd!
          ? new Date(grace)
          : null;
      const now = new Date();
      const recoveringWithoutSettlement =
        provider.status === "active" && Boolean(gracePeriodEnd);
      const status = (
        recoveringWithoutSettlement ? "PAST_DUE" : provider.status.toUpperCase()
      ) as SubscriptionStatus;
      const record = {
        ownerIdSnapshot: userId,
        dodoCustomerId: provider.customer.customer_id,
        productId: provider.product_id,
        status,
        periodStart,
        periodEnd,
        gracePeriodEnd,
        cancelAtPeriodEnd: provider.cancel_at_next_billing_date,
        cancelRequestedAt:
          provider.cancel_at_next_billing_date ||
          ["cancelled", "expired", "failed"].includes(provider.status)
            ? null
            : (existing?.cancelRequestedAt ?? null),
        currency: provider.currency,
        billingCountry: provider.billing.country,
        recurringAmountMinor: provider.recurring_pre_tax_amount,
        settledPaymentId,
        paymentConfirmedAt: hasPayment
          ? (existing?.paymentConfirmedAt ?? now)
          : null,
        lastEventAt: events[0]?.occurredAt ?? existing?.lastEventAt ?? null,
      };
      await tx.billingSubscription.upsert({
        where: { dodoSubscriptionId: subscriptionId },
        create: {
          ...record,
          userId,
          dodoSubscriptionId: subscriptionId,
          ...(provider.created_at
            ? { createdAt: new Date(provider.created_at) }
            : {}),
        },
        update: record,
      });

      // An obsolete subscription may update history, never replace a different
      // still-live projection. Reject simultaneous paid subscriptions for review.
      const projectingOther =
        user.dodoSubscriptionId && user.dodoSubscriptionId !== subscriptionId;
      if (projectingOther) {
        const current = await tx.billingSubscription.findFirst({
          where: { userId, dodoSubscriptionId: user.dodoSubscriptionId! },
        });
        const candidateCreatedAt =
          existing?.createdAt ??
          (provider.created_at ? new Date(provider.created_at) : null);
        if (
          current &&
          candidateCreatedAt &&
          candidateCreatedAt <= current.createdAt
        ) {
          await finishEvent();
          return true;
        }
        if (
          current &&
          (!["CANCELLED", "EXPIRED", "FAILED"].includes(current.status) ||
            (current.status === "CANCELLED" &&
              current.cancelAtPeriodEnd &&
              current.periodEnd &&
              current.periodEnd > new Date()))
        ) {
          if (["active", "past_due"].includes(provider.status))
            throw new BillingError("CONFLICTING_SUBSCRIPTIONS");
          await finishEvent();
          return true;
        }
        if (["cancelled", "expired", "failed"].includes(provider.status)) {
          await finishEvent();
          return true;
        }
      }
      const withinPaid = hasPayment && periodStart! <= now && now < periodEnd!;
      // cancel_at_next_billing_date leaves the provider active. Some cancellation
      // payloads report cancelled early with that flag; preserve only paid time.
      const scheduled =
        provider.cancel_at_next_billing_date &&
        provider.status === "cancelled" &&
        withinPaid;
      const eligible =
        (provider.status === "active" && hasPayment) ||
        (provider.status === "past_due" && hasPayment) ||
        scheduled;
      const projectionStatus: SubscriptionStatus =
        !hasPayment &&
        ["active", "pending", "past_due"].includes(provider.status)
          ? "PENDING"
          : scheduled
            ? "ACTIVE"
            : status;
      await tx.user.update({
        where: { id: userId },
        data: {
          plan: eligible ? "PAID" : "FREE",
          subscriptionStatus: projectionStatus,
          dodoSubscriptionId: subscriptionId,
          currentPeriodStart: periodStart,
          currentPeriodEnd: periodEnd,
          gracePeriodEnd,
          cancelAtPeriodEnd: provider.cancel_at_next_billing_date,
          billingCurrency: provider.currency,
          billingCountry: provider.billing.country,
          lastBillingEventAt: record.lastEventAt,
          billingStateVersion: { increment: 1 },
        },
      });
      // Keep the attempt open during initial activation until settlement or a
      // terminal provider state proves another checkout cannot conflict.
      if (
        hasPayment ||
        ["cancelled", "expired", "failed"].includes(provider.status)
      )
        await tx.checkoutAttempt.updateMany({
          where: {
            userId,
            productId: config.productId,
            status: {
              in: ["CREATING", "CUSTOMER_CREATING", "READY", "UNKNOWN"],
            },
            OR: [
              { id: provider.metadata.checkoutAttemptId ?? "" },
              {
                dodoSessionId: {
                  in: settlements
                    .map((p) => p.checkoutSessionId)
                    .filter((id): id is string => Boolean(id)),
                },
              },
            ],
          },
          data: {
            status: hasPayment ? "COMPLETED" : "FAILED",
            checkoutUrl: null,
            billingCountry: provider.billing.country,
          },
        });
      await finishEvent();
      return true;
    });
    if (result === "unsupported")
      throw new BillingError(
        "UNSUPPORTED_SUBSCRIPTION_PRODUCT",
        "This subscription changed to an unsupported product. Cancel it in the portal before starting a new checkout.",
        409,
      );
    if (result) return;
  }
  throw new BillingError("BILLING_SNAPSHOT_CHANGED");
}

export async function processBillingEvent(eventId: string) {
  const event = await db.billingWebhookEvent.findUnique({
    where: { id: eventId },
  });
  if (
    !event ||
    event.processedAt ||
    !["RECEIVED", "RETRY"].includes(event.state)
  )
    return;
  try {
    const data = normalizedBillingSchema.parse(event.normalizedData);
    if (event.businessId !== billingConfig().businessId)
      throw new BillingError("WEBHOOK_BUSINESS_MISMATCH");
    const customerId =
      data.kind === "payment"
        ? data.customerId
        : data.subscription.customer.customer_id;
    const subscriptionId =
      data.kind === "payment"
        ? data.subscriptionId
        : data.subscription.subscription_id;
    const deletionMetadata =
      data.kind === "payment" ? data.metadata : data.subscription.metadata;
    const deletion = await db.accountDeletionJob.findFirst({
      where: {
        OR: [
          { customerIds: { has: customerId } },
          ...(deletionMetadata.mailloopUserId
            ? [{ userId: deletionMetadata.mailloopUserId }]
            : []),
        ],
      },
    });
    if (deletion) {
      if (
        deletionMetadata.mailloopUserId &&
        deletionMetadata.mailloopUserId !== deletion.userId
      )
        throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
      // The signed event supplies durable recovery identifiers, never access.
      // Push avoids losing another late event racing the cancellation worker.
      await db.accountDeletionJob.updateMany({
        where: { userId: deletion.userId },
        data: {
          customerIds: { push: customerId },
          subscriptionIds: { push: subscriptionId },
          billingRequired: true,
          billingCancelledAt: null,
          completedAt: null,
          billingRecoveryVersion: { increment: 1 },
          nextAttemptAt: new Date(),
          nextBillingAttemptAt: new Date(),
        },
      });
      await db.billingWebhookEvent.updateMany({
        where: { id: eventId, processedAt: null },
        data: {
          state: "IGNORED_DELETED_OWNER",
          processedAt: new Date(),
          nextAttemptAt: null,
          failureCode: null,
          normalizedData: { deletedOwner: true },
          attempts: { increment: 1 },
        },
      });
      await runDeletionJob(deletion.userId, new Date(), {
        billingOnly: true,
      }).catch(() => false);
      return;
    }
    // Service-owned identity discovery; subsequent resources are owner-scoped.
    const owner = await db.user.findUnique({
      where: { dodoCustomerId: customerId },
      select: { id: true, deletionRequestedAt: true },
    });
    if (!owner) {
      const retained = await db.billingSubscription.findFirst({
        where: {
          userId: null,
          dodoCustomerId: customerId,
          ownerIdSnapshot: { not: null },
        },
        select: { ownerIdSnapshot: true },
      });
      if (!retained?.ownerIdSnapshot)
        throw new BillingError("BILLING_OWNER_UNRESOLVED");
      await recoverRetainedDeletion(retained.ownerIdSnapshot, customerId);
      // One bounded re-entry routes this verified event through the new job.
      return processBillingEvent(eventId);
    }
    if (owner.deletionRequestedAt) {
      await runDeletionJob(owner.id, new Date(), { billingOnly: true });
      throw new BillingError("DELETED_OWNER_RECOVERY_PENDING");
    }
    const metadata =
      data.kind === "payment" ? data.metadata : data.subscription.metadata;
    if (metadata.mailloopUserId && metadata.mailloopUserId !== owner.id)
      throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
    if (metadata.checkoutAttemptId) {
      const attempt = await db.checkoutAttempt.findFirst({
        where: { id: metadata.checkoutAttemptId, userId: owner.id },
      });
      if (!attempt) throw new BillingError("CHECKOUT_OWNERSHIP_MISMATCH");
    }
    if (data.kind === "payment" && !data.succeeded) {
      await db.billingWebhookEvent.updateMany({
        where: { id: eventId, processedAt: null },
        data: {
          state: "PROCESSED",
          processedAt: new Date(),
          nextAttemptAt: null,
          failureCode: null,
          attempts: { increment: 1 },
        },
      });
      return;
    }
    await reconcileBillingSubscription(owner.id, subscriptionId, eventId);
  } catch (error) {
    await db.$transaction(async (tx) => {
      await tx.billingWebhookEvent.updateMany({
        where: { id: eventId, processedAt: null },
        data: {
          state:
            event.attempts >= 7 ||
            (error instanceof BillingError &&
              [
                "UNSUPPORTED_SUBSCRIPTION_PRODUCT",
                "SUBSCRIPTION_OWNERSHIP_MISMATCH",
                "CHECKOUT_OWNERSHIP_MISMATCH",
                "CONFLICTING_SUBSCRIPTIONS",
              ].includes(error.code))
              ? "QUARANTINED"
              : "RETRY",
          failureCode:
            error instanceof BillingError
              ? error.code
              : "BILLING_RECONCILIATION_FAILED",
          attempts: { increment: 1 },
          nextAttemptAt: new Date(
            Date.now() +
              Math.min(3600_000, 30_000 * 2 ** Math.min(event.attempts, 7)),
          ),
        },
      });
    });
    throw new BillingError("BILLING_EVENT_RETRY");
  }
}
